// src/export/expo-compat.ts -- Expo SDK compatibility ranges, from the table
// vendored at expo-bundled-modules.json (generated by
// tools/gen-expo-bundled-modules.mjs from each SDK's `expo` package's own
// `bundledNativeModules.json`; the file records the source expo version and
// sha256 per SDK).
import { readFileSync } from "node:fs";

interface SdkEntry {
  readonly expoVersion: string;
  readonly sha256: string;
  readonly modules: Readonly<Record<string, string>>;
}
let cache: Readonly<Record<string, SdkEntry>> | null = null;
function table(): Readonly<Record<string, SdkEntry>> {
  cache ??= JSON.parse(readFileSync(new URL("./expo-bundled-modules.json", import.meta.url), "utf8")) as Record<string, SdkEntry>;
  return cache;
}

/** The compatible range Expo SDK `sdk` names for `pkg`, or null. */
export function expoCompatRange(sdk: number, pkg: string): string | null {
  return table()[String(sdk)]?.modules[pkg] ?? null;
}

/** The SDK's own react-native pin (used to refuse a table that contradicts the detected RN). */
export function expoSdkReactNative(sdk: number): string | null {
  return table()[String(sdk)]?.modules["react-native"] ?? null;
}

/** The `expo` package version the SDK's table was read from (its latest patch
 *  when generated): the table's ranges are consistent with that release. */
export function expoSdkExpoVersion(sdk: number): string | null {
  return table()[String(sdk)]?.expoVersion ?? null;
}
